entries[91197] = { ["name"] = "Simsstein mit sechs Klauen", ["text"] = "Wirken in 2 sek. 5\nDieses steinerne Objekt war vermutlich Teil einer schmückenden Auskragung an einem Wall oder einem Turm des dunklen Azjol-Nerub. Es stellt eine Kreatur dar, die halb Spinne und halb Insekt zu sein scheint und wurde mit grünen, violetten und goldenen Farben lackiert, die schwach fluoreszieren.\nSimsstein mit sechs Klauen\nWird beim Aufheben gebunden" }
