entries[91713] = { ["name"] = "Netherzauberschutz", ["text"] = "Wandelt Euren Effekt 'Zwielichtzauberschutz' in 'Netherzauberschutz' um.\n\nNetherzauberschutz\nAbsorbiert [ 3942 + (Zaubermacht * 0.807)] Zauberschaden. Hält 30 Sek. lang an. 30 Sek. Abklingzeit.\n\nWenn Ihr Schaden basorbiert, werdet Ihr mit dem Effekt 'Netherzauberschutz' belegt, der jeglichen durch diese Magieart erlittenen Schaden 12 Sek. lang um 15% verringert." }
entries[91721] = { ["name"] = "Kugelfischatmung", ["text"] = "Sofort 1 sek. Abklingzeit\nErmöglicht es dem Anwender, 30 Min. lang unter Wasser zu atmen." }
entries[91722] = { ["name"] = "Kugelfischatmung", ["text"] = "Sofort 1 sek. Abklingzeit\nEntzieht dem Kugelfisch Atem und ermöglicht 20 Sek. lang die Wasseratmung." }
entries[91723] = { ["name"] = "Schnitterstoß", ["text"] = "7 Meter Reichweite\nSofort 1 sek. Abklingzeit\nVerursacht in einem kegelförmigen Bereich vor dem Schnitterprototypen 13875 bis 16125 körperlichen Schaden. Erzeugt 20 Dampfkraft." }
entries[91724] = { ["name"] = "Zauberabwehr", ["text"] = "Sofort\nWährend Euer Zauber 'Inneres Feuer' aktiv ist, wird zusätzlich Euer erlittener Zauberschaden verringert. Zudem wird der Bewegungstempobonus Eures Zaubers 'Innerer Wille' um einen Prozentsatz erhöht." }
