entries[91726] = { ["name"] = "Schnittersturmangriff", ["text"] = "40 Energie 30 Meter Reichweite\nSofort 2 sek. Abklingzeit\nStürmt auf einen Gegner zu, verursacht 27750 bis 32250 körperlichen Schaden und betäubt ihn 4 Sek. lang." }
entries[91727] = { ["name"] = "Hochdruckschlag", ["text"] = "20 Energie 7 Meter Reichweite\nSofort 1 sek. Abklingzeit\nHoher Dampfdruck wird in einem mächtigen Angriff entladen. Verursacht 18500 bis 21500 körperlichen Schaden und stößt das Ziel zurück." }
