entries[91757] = { ["name"] = "Tyrandes Lieblingspuppe", ["text"] = "Wirken in 2 sek. 15\nTyrande Wisperwind ist die Hohepriesterin von Elune und, da sie nunmehr verheiratet ist, nicht mehr die Alleinherrscherin der Nachtelfen. Sie wuchs in der uralten Stadt Suramar auf, die zwar weit vom ersten Brunnen der Ewigkeit entfernt lag, aber nicht weit von den Brüdern Malfurion und Illidan Sturmgrimm. Tyrandes idyllische Kindheit sollte in scharfem Kontrast zu den Härten und Schicksalsschlägen ihres späteren Lebens stehen.\nTyrandes Lieblingspuppe\nAccountgebunden\nEinzigartig anlegbarSchmuck\n+321 Intelligenz\n85\nAnlegen: Gewinnt 20% der Grundmanakosten Eurer Zauber zurück und speichert es in der Puppe, um sie zu einem späteren Zeitpunkt freizugeben. Es können maximal 4200 Mana gespeichert werden.\nBenutzen: Entfesselt das gesamte in der Puppe gesammelte Mana, wodurch Ihr Mana in entsprechende Höhe gewinnt und allen Gegnern im Umkreis von 15 Metern pro Manapunkt 1 Arkanschaden zufügt. (1 Min Abklingzeit)" }
entries[91758] = { ["name"] = "Signal Flare Camo" }
entries[91759] = { ["name"] = "Skyshredder Explosion" }
entries[91760] = { ["name"] = "Transformation durchleben", ["text"] = "Sofort\nDurchlebt 20 Sek. lang die Transformation." }
entries[91761] = { ["name"] = "Knochen der Transformation", ["text"] = "Wirken in 2 sek. 15\nAls der erste Brunnen der Ewigkeit implodierte, sank das kulturelle Zentrum der Nachtelfen auf den Meeresgrund. Um ihrem sicheren Tod zu entfliehen, ging Königin Azshara einen Pakt mit einer größeren Macht ein, wahrscheinlich einem Alten Gott oder einem Elementar. Im Resultat wurden die überlebenden Hochgeborenen von einem Fluch befallen, der sie zu pervertierten, schlangenartigen Kreaturen transfomierte, die heute als Naga bekannt sind.\nKnochen der Transformation\nWird beim Aufheben gebunden\nSpielzeug\nBenutzen: Durchlebt 20 Sek. lang die Transformation. (10 Min Abklingzeit)" }
entries[91762] = { ["name"] = "Collier der einhundert Magi", ["text"] = "Wirken in 2 sek. 5\nWährend der Trollkriege wurden die Elfen von Quel'Thalas beinahe von den Amani bezwungen. In ihrer Verzweiflung lehrten die Elfen Menschen aus Arathor die Arkanmagie. Sie nahmen nur einhundert Schüler - die minimale Zahl, um die Trolle zu bezwingen. Die Menschen waren plumpe Magier, die jedoch eine natürliche Begabung für Magie hatten.\nCollier der einhundert Magi\nWird beim Aufheben gebunden" }
entries[91763] = { ["name"] = "Zauber akzeptieren" }
